const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const blocks=['Movilidad','Fuerza','Equilibrio','Salto','Control motor','Potencia','Acondicionamiento','Edema','Trote'];
const regions=['Rodilla','Hombro','Tobillo y pie','Cadera','Columna lumbar','Columna cervical','Codo y muñeca','General'];
const doseFields=[['series','Series','Ej. 3'],['reps','Repeticiones','Ej. 12'],['hold','Mantenimiento','Ej. 5 segundos'],['rest','Descanso entre series','Ej. 60 segundos'],['frequency','Frecuencia por día','Ej. 2 veces'],['weight','Carga / peso','Ej. 2 kg']];
const icons={grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',users:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M22 21v-2a4 4 0 0 0-3-3.87"/><circle cx="9" cy="7" r="4"/><path d="M16 3.13a4 4 0 0 1 0 7.75"/>',plus:'<path d="M12 5v14M5 12h14"/>',search:'<circle cx="10.5" cy="10.5" r="7.5"/><path d="m16 16 5 5"/>',play:'<path d="m9 5 11 7-11 7Z" fill="currentColor" stroke="none"/>',edit:'<path d="m16 3 5 5-12 12-6 1 1-6Z M14 5l5 5"/>',link:'<path d="M10 13a5 5 0 0 0 7 .5l3-3a5 5 0 0 0-7-7l-2 2M14 11a5 5 0 0 0-7-.5l-3 3a5 5 0 0 0 7 7l2-2"/>',settings:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3" fill="currentColor"/><circle cx="15" cy="17" r="3" fill="currentColor"/>',check:'<path d="m5 12 4 4L20 5"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',back:'<path d="M19 12H5m6-6-6 6 6 6"/>',up:'<path d="m6 15 6-6 6 6"/>',down:'<path d="m6 9 6 6 6-6"/>',trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7M14 10v7"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',video:'<rect x="3" y="5" width="13" height="14" rx="2"/><path d="m16 10 5-3v10l-5-3"/>',logout:'<path d="M9 4H4v16h5M10 12h11m-4-4 4 4-4 4"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',copy:'<rect x="8" y="8" width="13" height="13" rx="2"/><path d="M16 8V3H3v13h5"/>',shield:'<path d="m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6Z"/><path d="m8 11 3 3 5-5"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.grid}</svg>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const norm=s=>String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const uid=()=>{const b=crypto.getRandomValues(new Uint8Array(16));b[6]=(b[6]&15)|64;b[8]=(b[8]&63)|128;const h=[...b].map(n=>n.toString(16).padStart(2,'0')).join('');return h.slice(0,8)+'-'+h.slice(8,12)+'-'+h.slice(12,16)+'-'+h.slice(16,20)+'-'+h.slice(20)};
const date=s=>new Date(s).toLocaleString('es-AR',{day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'});
const brand=()=>'<a class="brand" href="#library" data-action="brand"><img src="logo.svg" alt=""><span>plan de rutina<span class="brand-period">.</span><small>POR TOMÁS BOSSIO</small></span></a>';
const btn=(label,act,kind='',ico='')=>`<button class="btn ${kind}" data-action="${act}">${ico?icon(ico):''}${label}</button>`;
let config={}, session=null, demo=false, data={exercises:[],routines:[]}, current='library',draft=null,dirty=false,search='',region='',block='',patientToken=new URLSearchParams(location.search).get('p'), preview=false;
let pendingFile=null,pendingURL=null,saveBusy=false, toastTimer, sessionRefresh=null;
const app=$('#app'), dialog=$('#dialog');
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',5000)}
function storeDemo(){try{localStorage.setItem('plan-rutina-demo-v1',JSON.stringify(data))}catch{throw Error('No se pudo guardar la prueba en este navegador. Liberá espacio o descargá un respaldo.')}}
function demoSeed(){return {exercises:[['Deslizamiento de talón','Movilidad','Rodilla','Flexión de rodilla con deslizamiento del talón sobre la superficie.'],['Extensión de rodilla sentado','Fuerza','Rodilla','Extensión de rodilla en posición sentada.'],['Equilibrio sobre una pierna','Equilibrio','Rodilla','Apoyo sobre una pierna para trabajar el equilibrio.'],['Elevación de talones','Fuerza','Tobillo y pie','Elevación de talones en posición de pie.'],['Puente de cadera','Control motor','Cadera','Elevación de pelvis con los pies apoyados.'],['Movilidad de tobillo','Movilidad','Tobillo y pie','Desplazamiento de la rodilla hacia adelante con apoyo del pie.']].map((a,i)=>({id:'demo-'+i,name:a[0],block:a[1],region:a[2],notes:a[3],source:'youtube',url:'',start:0,end:null,art:i})),routines:[]}}
async function api(path,options={},auth=true){if(auth)await ensureSession();const headers={apikey:config.publishableKey,...(auth?{Authorization:'Bearer '+session.access_token}:{}),...options.headers};if(options.body&&typeof options.body==='string')headers['Content-Type']='application/json';const r=await fetch(config.supabaseUrl+path,{...options,headers,cache:'no-store'});if(!r.ok){let e;try{e=await r.json()}catch{};if(r.status===401&&auth){session=null;sessionStorage.removeItem('plan-session');}throw Error(e?.message||e?.error_description||e?.msg||'No se pudo completar la operación. Revisá tu conexión.')}if(r.status===204)return null;const t=await r.text();return t?JSON.parse(t):null}
async function ensureSession(){if(!session)throw Error('Ingresá a tu cuenta para continuar.');if(Date.now()/1000<=session.expires_at-90)return;if(!sessionRefresh)sessionRefresh=(async()=>{const r=await fetch(config.supabaseUrl+'/auth/v1/token?grant_type=refresh_token',{method:'POST',headers:{apikey:config.publishableKey,'Content-Type':'application/json'},body:JSON.stringify({refresh_token:session.refresh_token})});if(!r.ok){session=null;sessionStorage.removeItem('plan-session');throw Error('Tu sesión venció. Volvé a ingresar.')}session=await r.json();sessionStorage.setItem('plan-session',JSON.stringify(session))})().finally(()=>sessionRefresh=null);await sessionRefresh}
async function loadData(){if(demo)return;const [ex,rs]=await Promise.all([api('/rest/v1/exercises?select=*&order=created_at.desc'),api('/rest/v1/routines?select=id,label,token,items,note,updated_at,revision,active&order=updated_at.desc')]);data={exercises:ex.map(x=>({...x.content,id:x.id})),routines:rs};}
function getExercise(id){return data.exercises.find(e=>e.id===id)}
function exerciseSnap(e){return {id:e.id,name:e.name,block:e.block,region:e.region,notes:e.notes,url:e.url,source:e.source,start:e.start,end:e.end,art:e.art}}

function planBlocks(r){return [...new Set([...(r.blockOrder||[]),...r.items.map(x=>x.exercise.block)])].filter(b=>r.items.some(x=>x.exercise.block===b))}
function orderedItems(r){return planBlocks(r).flatMap(b=>r.items.filter(x=>x.exercise.block===b))}
function newPlanItem(e){return {exercise:exerciseSnap(e),...Object.fromEntries(doseFields.map(([k])=>[k,e.defaults?.[k]||''])),notes:''}}
function editPlan(r){draft=structuredClone(r);draft.blockOrder=planBlocks(draft);dirty=false;current='editor';renderEditor();window.scrollTo(0,0)}
function normalizeName(s){return norm(s.trim().replace(/\s+/g,' '))}
function doseExtras(x){const extras=[['hold','Mantenimiento'],['rest','Descanso entre series'],['frequency','Frecuencia por día']].filter(([k])=>x[k]);return extras.length?`<dl class="table-extras">${extras.map(([k,l])=>`<div><dt>${l}</dt><dd>${esc(x[k])}</dd></div>`).join('')}</dl>`:''}

function nav(){return [['library','grid','Biblioteca',data.exercises.length],['routines','users','Mis rutinas',data.routines.length],['settings','settings','Configuración','']].map(([id,ico,label,count])=>`<button class="nav-item ${current===id?'active':''}" data-action="nav" data-id="${id}">${icon(ico)}<span>${label}</span>${count!==''?`<span class="count">${count}</span>`:''}</button>`).join('')}
function shell(content){app.innerHTML=`<div class="app-shell"><header class="topbar">${brand()}<nav class="desktop-nav" aria-label="Principal">${nav()}</nav><div class="account"><span class="avatar">TB</span><div><strong>Tomás Bossio</strong><span>Espacio profesional</span></div></div></header><main id="main" class="main">${demo?`<div class="demo-banner"><span><span class="demo-label">VERSIÓN DE PRUEBA</span> Explorá tu espacio. Por ahora, los cambios quedan en este navegador.</span><button data-action="nav" data-id="settings">Conectar mi cuenta ${icon('arrow')}</button></div>`:''}${content}<footer class="footer"><div>${brand()}<span>Ejercicio terapéutico. Planificación individual.</span></div><span>Tomás Bossio</span></footer></main><nav class="mobile-nav" aria-label="Navegación móvil">${nav()}</nav></div>`;bind()}
function illustration(i=0){return `<div class="exercise-illustration art-${Math.abs(Number(i)||0)%6}" role="img" aria-label="Imagen generada de referencia de un ejercicio; no reemplaza el video"></div>`}
function youtubeId(url){try{const u=new URL(url);if(['youtube.com','www.youtube.com','m.youtube.com','youtube-nocookie.com','www.youtube-nocookie.com'].includes(u.hostname)){const v=u.searchParams.get('v')||u.pathname.split('/')[2];return /^[\w-]{11}$/.test(v||'')?v:null}if(u.hostname==='youtu.be'){const v=u.pathname.slice(1);return /^[\w-]{11}$/.test(v)?v:null}}catch{}return null}
function safeUrl(u){try{const x=new URL(u);return x.protocol==='https:'||x.protocol==='http:'&&['localhost','127.0.0.1'].includes(x.hostname)}catch{return false}}

function blockSymbol(name){const drawings={
'Todos':'<rect x="5" y="5" width="12" height="12" rx="4"/><rect x="23" y="5" width="12" height="12" rx="4"/><rect x="5" y="23" width="12" height="12" rx="4"/><rect x="23" y="23" width="12" height="12" rx="4"/>',
'Movilidad':'<circle cx="22" cy="9" r="4"/><path d="m20 16-5 9 9 4 4 6M16 24l-8 9M19 18l10 3 5-5"/><path d="M5 17a15 15 0 0 1 9-12" stroke-width="1.5"/>',
'Fuerza':'<path d="M12 12v16M7 16v8M28 12v16M33 16v8M12 20h16"/><path d="M17 7h6" stroke-width="1.5"/>',
'Equilibrio':'<circle cx="20" cy="7" r="4"/><path d="M20 15v10l-3 11m3-11 10 1-5 7M20 17l-12 4m12-4 12 4"/><path d="M8 38h24" stroke-width="1.5"/>',
'Salto':'<circle cx="21" cy="9" r="4"/><path d="m20 17-2 10-8 3m8-3 9 2 5 6M19 19l-9-7m10 6 9-10"/><path d="M10 38h20M5 27v-8m0 0-3 3m3-3 3 3" stroke-width="1.5"/>',
'Control motor':'<circle cx="20" cy="20" r="12" stroke-width="1.5"/><circle cx="20" cy="20" r="5"/><path d="M20 2v6m0 24v6M2 20h6m24 0h6" stroke-width="2"/>',
'Potencia':'<path d="m24 3-15 20h11l-4 14 15-21H20Z"/>',
'Acondicionamiento':'<path d="M5 21h7l4-12 8 23 4-11h7"/><path d="M7 10a16 16 0 1 1-2 20" stroke-width="1.5"/>',
'Edema':'<path d="M20 4c-4 8-11 13-11 21a11 11 0 0 0 22 0c0-8-7-13-11-21Z" stroke-width="2"/><path d="M15 27a5 5 0 0 0 5 5" stroke-width="2"/>',
'Trote':'<circle cx="25" cy="7" r="4"/><path d="m23 15-7 10 9 4-2 8m-7-12-7 8H4m18-16 7 5 6-4M22 17l-9-4-5 5"/>'};return `<svg viewBox="0 0 40 40" fill="none" stroke="currentColor" stroke-width="3.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${drawings[name]||drawings.Todos}</svg>`}

function imageCard(e,i){const yt=youtubeId(e.url);return `<div class="exercise-image block-${blocks.indexOf(e.block)}">${yt?`<img class="thumb" src="https://i.ytimg.com/vi/${yt}/hqdefault.jpg" alt="" loading="lazy">`:illustration(e.art??i)}<span class="exercise-badge">${blockSymbol(e.block)} ${esc(e.block)}</span><span class="play">${icon('play')}</span><span class="source-badge">${e.url?(e.source==='youtube'?'YouTube':e.source==='file'?'Video propio':'Video externo'):'Imagen de referencia'}</span></div>`}
function renderLibrary(){shell(`<section class="movement-hero"><div class="movement-copy"><span class="eyebrow">EJERCICIO TERAPÉUTICO · PLANIFICACIÓN INDIVIDUAL</span><h1>BIENVENIDO</h1><p>Seleccioná los ejercicios. Personalizá las indicaciones.<br>Acompañá a cada paciente también fuera del consultorio.</p><div class="hero-actions">${btn('Crear una rutina','new-routine','','plus')}<button class="hero-library-link" data-action="scroll-library">Explorar biblioteca ${icon('down')}</button></div><div class="hero-signature"><span class="signature-line"></span> Tomás Bossio · Plan de rutina</div></div><div class="movement-visual"><img src="assets/movement-hero.webp" alt="Imagen decorativa de un hombre y una mujer haciendo ejercicio, con baja opacidad sobre un fondo azul" fetchpriority="high"><span class="floating-label label-top"><span class="label-icon">${icon('video')}</span><span>Biblioteca de ejercicios<strong>Organizada y reutilizable</strong></span></span><span class="floating-label label-bottom"><span class="label-icon coral">${icon('check')}</span><span>Rutinas individuales<strong>Indicaciones precisas</strong></span></span><span class="visual-caption">EJERCICIO · FUNCIÓN · MOVIMIENTO</span></div></section><div class="workspace-strip"><div><span class="strip-icon">${icon('video')}</span><strong>${data.exercises.length.toString().padStart(2,'0')}</strong><span>ejercicios en tu biblioteca</span></div><div><span class="strip-icon peach">${icon('users')}</span><strong>${data.routines.length.toString().padStart(2,'0')}</strong><span>planes individuales</span></div><div><span class="strip-icon lilac">${icon('grid')}</span><strong>09</strong><span>formas de trabajar</span></div><span class="strip-caption">CRITERIO CLÍNICO. ATENCIÓN PERSONAL.</span></div><section id="library-section"><div class="section-line library-heading"><div><span class="eyebrow muted">BIBLIOTECA PROFESIONAL</span><h2>Tu biblioteca de ejercicios<span class="coral-dot">.</span></h2><p class="small muted">Ejercicios organizados por objetivo y región corporal.</p></div>${btn('Nuevo ejercicio','new-exercise','secondary','plus')}</div><div class="block-selector" aria-label="Filtrar por bloque">${['Todos',...blocks].map((x,i)=>`<button class="block-tile ${block===x||(!block&&x==='Todos')?'active':''}" data-action="filter-block" data-id="${x==='Todos'?'':x}"><span class="block-art block-art-${i}">${blockSymbol(x)}</span><span>${x}</span></button>`).join('')}</div><div class="toolbar library-toolbar"><label class="search"><span class="sr-only">Buscar ejercicio</span>${icon('search')}<input id="search" placeholder="¿Qué ejercicio estás buscando?" value="${esc(search)}"></label><select id="region-filter" aria-label="Región corporal"><option value="">Todas las regiones</option>${regions.map(x=>`<option ${region===x?'selected':''}>${x}</option>`).join('')}</select><span id="result-count" class="results-count"></span></div><div id="exercise-results"></div></section>`);renderCards();$('#search').oninput=e=>{search=e.target.value;renderCards()};$('#region-filter').onchange=e=>{region=e.target.value;renderCards()};document.querySelector('[data-action="scroll-library"]').onclick=()=>$('#library-section').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})}
function renderCards(){const list=data.exercises.filter(e=>(!region||region===e.region)&&(!block||block===e.block)&&norm(e.name+' '+e.notes).includes(norm(search)));$('#result-count').textContent=list.length+' ejercicios';$('#exercise-results').innerHTML=list.length?`<div class="cards">${list.map((e,i)=>`<article class="exercise-card"><button style="padding:0;text-align:left;background:none" data-action="watch" data-id="${esc(e.id)}" aria-label="Ver ${esc(e.name)}">${imageCard(e,i)}</button><div class="card-body"><div class="card-meta">${esc(e.region)}<span>·</span>${esc(e.block)}</div><h3>${esc(e.name)}</h3><p>${esc(e.notes||'Listo para personalizar en una rutina.')}</p><div class="card-actions"><button class="text-btn" data-action="assign" data-id="${esc(e.id)}">${icon('plus')} Agregar a rutina</button><button class="icon-btn" data-action="edit-exercise" data-id="${esc(e.id)}" aria-label="Editar ${esc(e.name)}">${icon('edit')}</button></div></div></article>`).join('')}</div>`:`<div class="empty">${icon('video')}<h3>${data.exercises.length?'No encontramos ejercicios':'Tu biblioteca empieza acá'}</h3><p>${data.exercises.length?'Probá con otro nombre, región o bloque.':'Agregá un video y reutilizalo en todas las rutinas que necesites.'}</p>${btn('Agregar ejercicio','new-exercise','','plus')}</div>`;bind($('#exercise-results'))}
function renderRoutines(){shell(`<div class="page-heading"><div><p class="eyebrow" style="margin:0 0 9px">PLANES QUE ACOMPAÑAN</p><h1>Rutinas individuales.</h1><p>Actualizá los ejercicios. El enlace sigue siendo el mismo.</p></div>${btn('Nueva rutina','new-routine','','plus')}</div><div class="toolbar"><label class="search">${icon('search')}<input id="routine-search" placeholder="Buscar paciente o referencia…" aria-label="Buscar rutina"></label></div><div id="routine-results"></div>`);renderRoutineRows('');$('#routine-search').oninput=e=>renderRoutineRows(e.target.value)}
function renderRoutineRows(q){const rs=data.routines.filter(r=>norm(r.label).includes(norm(q)));$('#routine-results').innerHTML=rs.length?`<div class="routine-list">${rs.map(r=>`<article class="routine-row"><span class="avatar">${esc(r.label.split(' ').filter(Boolean).map(x=>x[0]).slice(0,2).join('').toUpperCase())}</span><div class="details"><h3>${esc(r.label)}</h3><p>${r.items.length} ejercicios · ${date(r.updated_at)}</p></div><span class="pill">${r.active?'Activa':'Pausada'}</span><div class="actions"><button class="btn secondary" data-action="edit-routine" data-id="${esc(r.id)}">${icon('edit')}Editar</button><button class="btn secondary" data-action="preview-routine" data-id="${esc(r.id)}">${icon('play')}Ver</button><button class="btn secondary" data-action="duplicate-routine" data-id="${esc(r.id)}">${icon('copy')}Duplicar</button><button class="btn" data-action="share-routine" data-id="${esc(r.id)}">${icon('link')}Enlace</button><button class="icon-btn" data-action="delete-routine" data-id="${esc(r.id)}" aria-label="Eliminar rutina de ${esc(r.label)}">${icon('trash')}</button></div></article>`).join('')}</div>`:`<div class="empty">${icon('users')}<h3>${q?'No hay coincidencias':'Cada persona, su propio plan'}</h3><p>Creá una rutina, seleccioná los ejercicios y ajustá las indicaciones para ese paciente.</p>${btn('Crear primera rutina','new-routine','','plus')}</div>`;bind($('#routine-results'))}
function newRoutine(exId){draft={id:uid(),label:'',token:uid()+uid().replaceAll('-',''),items:[],blockOrder:[...blocks],note:'',revision:0,active:true};if(exId)draft.items.push(newPlanItem(getExercise(exId)));dirty=true;current='editor';renderEditor()}
function renderEditor(){shell(`<div class="page-heading"><div><button class="text-btn" data-action="nav" data-id="routines">${icon('back')} Volver a mis rutinas</button><h1 style="margin-top:12px">${draft.revision?'Editar rutina':'Crear una rutina'}</h1><p>Seleccioná los ejercicios y completá las indicaciones individuales.</p></div><span id="dirty-label" class="unsaved">${dirty?'Cambios sin guardar':'Guardada'}</span></div><div class="editor-layout"><div><div class="panel"><label class="field">Nombre y apellido del paciente<input id="plan-label" maxlength="80" value="${esc(draft.label)}" placeholder="Ej. Martín González" autocomplete="off"><small>El paciente verá su nombre y apellido en la bienvenida.</small></label><label class="field" style="margin-bottom:0">Mensaje para el paciente<textarea id="plan-note" maxlength="1500" placeholder="Indicaciones generales para esta rutina…">${esc(draft.note)}</textarea></label></div><div class="section-line"><h2>Ejercicios de la rutina</h2>${btn('Seleccionar ejercicios','choose-exercises','secondary','plus')}</div><div id="plan-items">${renderPlanItems()}</div></div><aside class="panel sticky"><span class="eyebrow muted">TU PLAN, SIEMPRE AL DÍA</span><h3 style="margin-top:13px">${draft.items.length} ejercicios seleccionados</h3><p class="small muted">Los cambios se muestran al paciente cuando guardás la rutina y vuelve a abrir su enlace.</p><div class="divider"></div><div class="action-stack">${btn('Guardar cambios','save-routine','','check')}${btn('Vista del paciente','preview-draft','secondary','play')}${draft.revision?btn('Copiar enlace','share-draft','secondary','link'):''}${draft.revision?btn('Enviar por WhatsApp','whatsapp-draft','secondary','link'):''}${draft.revision?btn('Duplicar rutina','duplicate-draft','secondary','copy'):''}${draft.revision?btn('Ver y limpiar historial','history','ghost','clock'):''}${draft.revision?btn('Eliminar rutina','delete-draft','danger','trash'):''}</div><div class="divider"></div><label class="check-row" style="border:0;padding:0"><input type="checkbox" id="plan-active" ${draft.active?'checked':''}><span class="small">Rutina activa</span></label><p class="tiny muted" style="margin-top:9px">Si la pausás, el enlace deja de mostrar los ejercicios. Podés volver a activarla.</p>${demo?'<div class="notice warn" style="margin-top:20px">En esta prueba, guardar afecta solo a este navegador. El enlace para pacientes se habilita al conectar tu cuenta.</div>':''}</aside></div>`);$('#plan-label').oninput=e=>{draft.label=e.target.value;markDirty()};$('#plan-note').oninput=e=>{draft.note=e.target.value;markDirty()};$('#plan-active').onchange=e=>{draft.active=e.target.checked;markDirty()};$$('[data-dose]').forEach(el=>el.oninput=()=>{const item=draft.items[+el.dataset.index];item[el.dataset.dose]=el.value;markDirty()})}
function markDirty(){dirty=true;if($('#dirty-label'))$('#dirty-label').textContent='Cambios sin guardar'}
function renderPlanItems(){if(!draft.items.length)return `<div class="empty">${icon('grid')}<h3>Elegí los ejercicios de este plan</h3><p>Una tilde agrega el ejercicio con sus valores habituales. Después podés ajustarlos.</p>${btn('Abrir biblioteca','choose-exercises','','plus')}</div>`;const bs=planBlocks(draft),ordered=orderedItems(draft);return bs.map((b,bi)=>{const entries=draft.items.map((x,i)=>({x,i})).filter(({x})=>x.exercise.block===b);return `<div class="block-order-head"><h3 class="block-heading">${bi+1}. ${b} · ${entries.length}</h3><div><button class="icon-btn" data-action="block-up" data-id="${esc(b)}" aria-label="Subir bloque ${b}" ${bi===0?'disabled':''}>${icon('up')}</button><button class="icon-btn" data-action="block-down" data-id="${esc(b)}" aria-label="Bajar bloque ${b}" ${bi===bs.length-1?'disabled':''}>${icon('down')}</button></div></div>${entries.map(({x,i},ei)=>`<article class="plan-item"><div class="plan-item-head"><span class="number">${ordered.indexOf(x)+1}</span><h3>${esc(x.exercise.name)}</h3><button class="icon-btn" data-action="move-up" data-id="${i}" aria-label="Subir ejercicio ${esc(x.exercise.name)}" ${ei===0?'disabled':''}>${icon('up')}</button><button class="icon-btn" data-action="move-down" data-id="${i}" aria-label="Bajar ejercicio ${esc(x.exercise.name)}" ${ei===entries.length-1?'disabled':''}>${icon('down')}</button><button class="icon-btn" data-action="remove-item" data-id="${i}" aria-label="Quitar ejercicio ${esc(x.exercise.name)}">${icon('close')}</button></div><div class="grid3">${doseFields.map(([k,label,ph])=>`<label class="field">${label}<input maxlength="80" data-dose="${k}" data-index="${i}" placeholder="${ph}" value="${esc(x[k])}"></label>`).join('')}</div><label class="field" style="margin-bottom:0">Indicación individual (opcional)<input maxlength="500" data-dose="notes" data-index="${i}" value="${esc(x.notes)}" placeholder="Una aclaración para este paciente…"></label>${getExercise(x.exercise.id)?`<button class="text-btn item-refresh" data-action="refresh-item" data-id="${i}">${icon('video')}Actualizar video e indicaciones desde la biblioteca</button>`:''}</article>`).join('')}`}).join('')}
function modal(title,body,wide=false){dialog.innerHTML=`<div class="dialog-head"><h2>${title}</h2><button class="icon-btn" data-action="close" aria-label="Cerrar">${icon('close')}</button></div><div class="dialog-body">${body}</div>`;dialog.style.maxWidth=wide?'850px':'720px';if(!dialog.open)dialog.showModal();bind(dialog)}
function closeModal(){stopMedia(dialog);dialog.close();if(pendingURL){URL.revokeObjectURL(pendingURL);pendingURL=null}pendingFile=null}
function chooseExercises(){const selected=new Set(draft.items.map(x=>x.exercise.id));modal('Seleccionar ejercicios',`<p class="small muted" style="margin-bottom:18px">Cada tilde agrega el ejercicio a esta rutina con sus valores habituales. Los cambios se publican cuando guardás.</p><div class="toolbar"><label class="search">${icon('search')}<input id="choose-search" placeholder="Buscar ejercicio…" aria-label="Buscar ejercicio"></label><select id="choose-region" aria-label="Región"><option value="">Todas las regiones</option>${regions.map(x=>`<option>${x}</option>`).join('')}</select></div><div class="chooser-list" id="chooser"></div><div class="dialog-footer"><span id="chosen-count" class="selection-count" style="margin-right:auto;align-self:center"></span>${btn('Volver a la rutina','finish-selection','','check')}</div>`);const draw=()=>{const q=$('#choose-search').value,reg=$('#choose-region').value;$('#chooser').innerHTML=data.exercises.filter(e=>(!reg||e.region===reg)&&norm(e.name+' '+e.block).includes(norm(q))).map(e=>`<label class="check-row"><input type="checkbox" value="${esc(e.id)}" ${selected.has(e.id)?'checked':''}><span>${esc(e.name)}<small>${esc(e.region)} · ${esc(e.block)}${e.url?'':' · Ejemplo sin video'}</small></span></label>`).join('')||'<p class="muted small">No hay ejercicios para esta búsqueda.</p>';$$('#chooser input').forEach(el=>el.onchange=()=>{if(el.checked){selected.add(el.value);if(!draft.items.some(x=>x.exercise.id===el.value))draft.items.push(newPlanItem(getExercise(el.value)))}else{selected.delete(el.value);draft.items=draft.items.filter(x=>x.exercise.id!==el.value)}markDirty();count()});count()};const count=()=>$('#chosen-count').textContent=selected.size+' seleccionados';$('#choose-search').oninput=draw;$('#choose-region').onchange=draw;draw();dialog.querySelector('[data-action="finish-selection"]').onclick=closeModal;dialog.addEventListener('close',()=>{if(current==='editor')renderEditor()},{once:true})}
function mediaHTML(e){if(!e.url)return `<div class="demo-video-visual">${illustration(e.art||0)}<span class="demo-video-label">Imagen de referencia · agregá el video del ejercicio</span></div>`;const yt=youtubeId(e.url);if(yt)return `<iframe class="media" title="${esc(e.name)}" src="https://www.youtube-nocookie.com/embed/${yt}?rel=0&playsinline=1&start=${Math.floor(e.start||0)}${e.end?'&end='+Math.floor(e.end):''}" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" allowfullscreen loading="lazy" referrerpolicy="strict-origin-when-cross-origin"></iframe><p class="tiny muted">Si el video no se reproduce, <a href="https://www.youtube.com/watch?v=${yt}&t=${Math.floor(e.start||0)}s" target="_blank" rel="noopener noreferrer">abrilo en YouTube</a>.</p>`;if(!safeUrl(e.url)&&!e.url.startsWith('blob:'))return '<p class="error-text">El enlace de video no es válido.</p>';return `<video class="media" controls playsinline preload="metadata" src="${esc(e.url)}" data-start="${Number(e.start)||0}" data-end="${Number(e.end)||0}"></video><p class="tiny muted">${e.start||e.end?'Se muestra el fragmento seleccionado. ':''}<a href="${esc(e.url)}" target="_blank" rel="noopener noreferrer">Abrir video original</a></p>`}
function bindVideos(root=document){root.querySelectorAll('video[data-start]').forEach(v=>{const start=+v.dataset.start,end=+v.dataset.end;let guarding=false;v.onloadedmetadata=()=>{if(start>=v.duration){v.insertAdjacentHTML('afterend','<p class="error-text">El comienzo del fragmento supera la duración del video. Consultá con Tomás.</p>');return}if(start)v.currentTime=start};v.onplay=()=>{if((end&&v.currentTime>=end)||v.currentTime<start)v.currentTime=start};v.onseeked=()=>{if(guarding)return;if(v.currentTime<start||end&&v.currentTime>end){guarding=true;v.currentTime=start;setTimeout(()=>guarding=false,100)}};v.ontimeupdate=()=>{if(end&&v.currentTime>=end){v.pause();v.currentTime=start}};v.onerror=()=>{if(!v.nextElementSibling?.classList.contains('media-error'))v.insertAdjacentHTML('afterend','<p class="error-text media-error">No se pudo cargar este video. El sitio de origen puede impedir su reproducción. Probá el enlace original o consultá con Tomás.</p>')}})}
function stopMedia(root){root.querySelectorAll('video').forEach(v=>v.pause());root.querySelectorAll('iframe').forEach(f=>f.src='about:blank')}
function watch(id){const e=getExercise(id);modal(esc(e.name),`<div class="card-meta">${esc(e.region)} · ${esc(e.block)}</div><div class="media-wrap">${mediaHTML(e)}</div><p class="small muted">${esc(e.notes)}</p>${e.start||e.end?`<p class="tiny muted" style="margin-top:12px">Fragmento: ${e.start||0} s ${e.end?'a '+e.end+' s':'hasta el final'}.</p>`:''}<div class="dialog-footer">${btn('Editar ejercicio','edit-exercise','secondary','edit').replace('data-action="edit-exercise"',`data-action="edit-exercise" data-id="${esc(id)}"`)}</div>`);bindVideos(dialog)}
function exerciseForm(id){if(dialog.open)closeModal();const e=id?getExercise(id):{name:'',region:'Rodilla',block:'Movilidad',source:'youtube',url:'',start:0,end:null,notes:''};modal(id?'Editar ejercicio':'Nuevo ejercicio',`<form id="exercise-form"><div id="exercise-error" class="error-text" role="alert"></div><label class="field">Nombre del ejercicio (opcional)<input name="name" maxlength="120" value="${esc(e.name)}" placeholder="Ej. Extensión de rodilla sentado"></label><div class="grid2"><label class="field">Región corporal<select name="region">${regions.map(x=>`<option ${e.region===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="field">Bloque<select name="block">${blocks.map(x=>`<option ${e.block===x?'selected':''}>${x}</option>`).join('')}</select></label></div><label class="field">Origen del video<select id="video-source" name="source"><option value="youtube" ${e.source==='youtube'?'selected':''}>Enlace de YouTube</option><option value="external" ${e.source==='external'?'selected':''}>Enlace directo a un video (MP4 / WebM)</option><option value="file" ${e.source==='file'?'selected':''}>Subir desde mi computadora o celular</option></select></label><div id="url-field"><label class="field">Enlace del video<input type="url" name="url" id="video-url" value="${esc(e.url)}" placeholder="https://www.youtube.com/watch?v=…"><small>Para un artículo, necesitás el enlace directo al archivo de video, no a la página del artículo.</small></label></div><div id="file-field" class="file-area" style="display:none;margin-bottom:16px"><label class="field">Archivo de video<input id="video-file" type="file" accept="video/mp4,video/webm,video/quicktime"><small>Máximo 50 MB por archivo. MP4 con video H.264 es la opción más compatible con celulares.${demo?' En modo prueba el archivo solo se puede previsualizar; no se sube.':''}</small></label>${e.url?'<p class="tiny muted">Ya hay un video guardado. Elegí otro solo si querés reemplazarlo.</p>':''}</div><div class="toolbar">${btn('Previsualizar video','preview-video','secondary','play')}</div><div id="video-preview"></div><div class="grid2"><label class="field">Mostrar desde (segundos)<input type="number" name="start" min="0" step="1" value="${e.start||0}"></label><label class="field">Mostrar hasta (segundos)<input type="number" name="end" min="1" step="1" value="${e.end||''}" placeholder="Hasta el final"></label></div><p class="tiny muted" style="margin-bottom:17px">Selecciona el fragmento que se reproduce. El archivo original se conserva completo; esto no reduce su tamaño.</p><label class="field">Indicaciones generales<textarea name="notes" maxlength="1500" placeholder="Cómo realizarlo y qué tener en cuenta…">${esc(e.notes)}</textarea><small>Podés agregar una indicación general y ajustar los valores para cada paciente.</small></label><h3 class="defaults-title">Valores habituales (opcionales)</h3><p class="small muted" style="margin-bottom:15px">Se copian al seleccionar este ejercicio y después podés cambiarlos para cada paciente.</p><div class="grid3">${doseFields.map(([k,l,ph])=>`<label class="field">${l}<input name="default_${k}" maxlength="80" placeholder="${ph}" value="${esc(e.defaults?.[k]||'')}"></label>`).join('')}</div><div class="dialog-footer">${id?`<button type="button" class="btn danger" data-action="delete-exercise" data-id="${esc(id)}" style="margin-right:auto">${icon('trash')}Eliminar</button>`:''}<button type="button" class="btn secondary" data-action="close">Cancelar</button><button type="submit" class="btn" id="exercise-submit">${icon('check')}Guardar ejercicio</button></div></form>`);const f=$('#exercise-form');const updateSource=()=>{const file=$('#video-source').value==='file';$('#url-field').style.display=file?'none':'block';$('#file-field').style.display=file?'block':'none';$('#video-url').required=!file};$('#video-source').onchange=updateSource;updateSource();$('#video-file').onchange=()=>{pendingFile=$('#video-file').files[0]||null;if(pendingURL)URL.revokeObjectURL(pendingURL);pendingURL=pendingFile?URL.createObjectURL(pendingFile):null};dialog.querySelector('[data-action="preview-video"]').onclick=ev=>{ev.preventDefault();const v=Object.fromEntries(new FormData(f));v.url=v.source==='file'?(pendingURL||e.url):v.url;v.name=v.name||'Vista previa';v.start=+v.start||0;v.end=+v.end||null;if(!v.url){toast('Elegí un video o pegá su enlace.');return}$('#video-preview').innerHTML=`<div class="media-wrap">${mediaHTML(v)}</div>`;bindVideos($('#video-preview'))};f.onsubmit=async ev=>{ev.preventDefault();const b=$('#exercise-submit');b.disabled=true;$('#exercise-error').textContent='';try{const v=Object.fromEntries(new FormData(f));v.name=v.name.trim()||'Ejercicio '+(data.exercises.length+1);v.defaults=Object.fromEntries(doseFields.map(([k])=>[k,String(v['default_'+k]||'').trim()]));doseFields.forEach(([k])=>delete v['default_'+k]);v.start=Number(v.start)||0;v.end=v.end?Number(v.end):null;if(!Number.isFinite(v.start)||v.start<0||v.end!==null&&(!Number.isFinite(v.end)||v.end<0))throw Error('Revisá los segundos del fragmento.');if(v.end&&v.end<=v.start)throw Error('El final del fragmento debe ser posterior al comienzo.');if(v.source==='file'){if(pendingFile){if(demo)throw Error('Para guardar archivos propios primero conectá tu cuenta. Podés probar con un enlace de YouTube.');if(pendingFile.size>50*1024*1024)throw Error('El archivo supera los 50 MB. Recortalo o subilo a YouTube como no listado.');if(!['video/mp4','video/webm','video/quicktime'].includes(pendingFile.type))throw Error('Usá un archivo MP4, WebM o MOV.');const ext={'video/mp4':'mp4','video/webm':'webm','video/quicktime':'mov'}[pendingFile.type];const path=uid()+'.'+ext;await api('/storage/v1/object/exercise-videos/'+path,{method:'POST',headers:{'Content-Type':pendingFile.type,'x-upsert':'false'},body:pendingFile});v.url=config.supabaseUrl+'/storage/v1/object/public/exercise-videos/'+path}else if(!e.url)throw Error('Seleccioná un archivo de video.');else v.url=e.url}else if(!safeUrl(v.url))throw Error('Pegá un enlace HTTPS válido.');if(v.source==='youtube'&&!youtubeId(v.url))throw Error('No reconocemos este enlace de YouTube. Revisá que sea el enlace de un video.');v.id=id||uid();if(!demo){await api('/rest/v1/exercises?on_conflict=id',{method:'POST',headers:{Prefer:'resolution=merge-duplicates'},body:JSON.stringify({id:v.id,content:v})});await loadData()}else{const idx=data.exercises.findIndex(x=>x.id===id);if(idx>=0)data.exercises[idx]=v;else data.exercises.unshift(v);storeDemo()}closeModal();current='library';renderLibrary();toast('Ejercicio guardado. Las rutinas existentes conservan su versión hasta que las actualices.')}catch(err){$('#exercise-error').textContent=err.message;b.disabled=false}}}
async function deleteExercise(id){if(!await confirmDialog('¿Eliminar este ejercicio?','Se quitará de la biblioteca. Las rutinas ya guardadas conservan su video e indicaciones.'))return;try{if(!demo)await api('/rest/v1/exercises?id=eq.'+encodeURIComponent(id),{method:'DELETE'});data.exercises=data.exercises.filter(e=>e.id!==id);if(demo)storeDemo();closeModal();renderLibrary();toast('Ejercicio eliminado de la biblioteca.')}catch(e){toast(e.message)}}
function confirmDialog(title,body){return new Promise(resolve=>{let settled=false;const done=v=>{if(settled)return;settled=true;resolve(v)};modal(title,`<p class="small muted">${body}</p><div class="dialog-footer"><button class="btn secondary" id="confirm-no">Cancelar</button><button class="btn" id="confirm-yes">Continuar</button></div>`);$('#confirm-no').onclick=()=>{closeModal();done(false)};$('#confirm-yes').onclick=()=>{done(true);closeModal()};dialog.addEventListener('close',()=>done(false),{once:true})})}
async function saveRoutine(){if(saveBusy)return;if(!draft.label.trim()){toast('Agregá el nombre y apellido del paciente.');$('#plan-label').focus();return}if(!draft.items.length){toast('Seleccioná al menos un ejercicio.');return}if(!demo&&draft.items.some(x=>!x.exercise.url)){toast('Hay un ejercicio sin video. Completalo antes de compartir la rutina.');return}if(data.routines.some(r=>r.id!==draft.id&&normalizeName(r.label)===normalizeName(draft.label))){toast('Ya existe una rutina para este nombre. Editá esa rutina para mantener su enlace.');return}saveBusy=true;const rollbackDraft=structuredClone(draft),rollbackData=structuredClone(data);draft.items=orderedItems(draft);$$('[data-action="save-routine"]').forEach(b=>b.disabled=true);try{draft.label=draft.label.trim().replace(/\s+/g,' ');const previous=data.routines.find(r=>r.id===draft.id);if(previous&&JSON.stringify([previous.label,previous.items,previous.note,previous.active])===JSON.stringify([draft.label,draft.items,draft.note,draft.active])){dirty=false;renderEditor();toast('No hay cambios nuevos para guardar.');return}if(demo){const prev=data.routines.find(x=>x.id===draft.id);const history=prev?{updated_at:prev.updated_at,items:prev.items,note:prev.note,label:prev.label,revision:prev.revision}:null;draft={...draft,revision:draft.revision+1,updated_at:new Date().toISOString(),history:[...(prev?.history||[]),...(history?[history]:[])]};const idx=data.routines.findIndex(x=>x.id===draft.id);if(idx>=0)data.routines[idx]=structuredClone(draft);else data.routines.unshift(structuredClone(draft));storeDemo()}else{const result=await api('/rest/v1/rpc/save_routine',{method:'POST',body:JSON.stringify({p_id:draft.id,p_label:draft.label,p_token:draft.token,p_items:draft.items,p_note:draft.note,p_active:draft.active,p_expected_revision:draft.revision})});draft={...draft,...result};await loadData()}dirty=false;renderEditor();toast(demo?'Prueba guardada en este navegador.':'Rutina actualizada. El enlace sigue siendo el mismo.')}catch(e){if(demo){draft=rollbackDraft;data=rollbackData;dirty=true}toast(e.message.includes('CONFLICT')?'La rutina cambió en otro dispositivo. Volvé a abrirla antes de guardar.':e.message.includes('plan_unique_patient_name')?'Ya existe una rutina para este nombre y apellido. Editá la existente.':e.message)}finally{saveBusy=false;$$('[data-action="save-routine"]').forEach(b=>b.disabled=false)}}
async function copyText(t){try{await navigator.clipboard.writeText(t);toast('Enlace copiado. Ya podés pegarlo en WhatsApp.')}catch{modal('Copiar enlace',`<p class="small muted">Seleccioná el enlace y copialo.</p><textarea readonly style="width:100%;margin-top:15px">${esc(t)}</textarea>`);dialog.querySelector('textarea').select()}}
function routineURL(r){const u=new URL(location.href);u.search='';u.hash='';u.searchParams.set('p',r.token);return u.href}
function share(r){if(demo){toast('Los enlaces se habilitan al conectar tu cuenta. Esta prueba solo está en tu navegador.');return}if(!r.active){toast('Activá y guardá la rutina antes de compartir el enlace.');return}if(dirty&&draft?.id===r.id){toast('Guardá los cambios antes de copiar el enlace.');return}copyText(routineURL(r))}
async function showHistory(){try{const h=demo?[...(data.routines.find(r=>r.id===draft.id)?.history||[])].reverse():await api('/rest/v1/routine_history?routine_id=eq.'+draft.id+'&select=revision,label,note,items,created_at&order=revision.desc');modal('Historial de la rutina',`<p class="small muted" style="margin-bottom:15px">Solo vos ves las versiones anteriores. Borrarlas conserva la rutina actual y su enlace. No hay copias adicionales de los videos.</p>${h.length?`<div class="history-tools">${btn('Borrar historial y conservar la actual','clear-history','danger','trash')}</div>`+h.map(x=>`<div class="history-entry"><div class="history-version"><strong class="small">Versión ${x.revision} · ${date(x.created_at||x.updated_at)}</strong><button class="icon-btn" data-action="delete-history-version" data-id="${x.revision}" aria-label="Eliminar versión ${x.revision}">${icon('trash')}</button></div><p>${x.items.map(y=>esc(y.exercise.name)+': '+esc(y.series||'—')+' series × '+esc(y.reps||'—')).join('<br>')}</p>${x.note?`<p>${esc(x.note)}</p>`:''}</div>`).join(''):'<div class="notice">Todavía no hay versiones anteriores.</div>'}`)}catch(e){toast(e.message)}}
function patientView(r,isPreview=false){stopMedia(document);const grouped=planBlocks(r),items=orderedItems(r);preview=isPreview;app.innerHTML=`${isPreview?`<div class="preview-label">Vista del paciente ${dirty?'· cambios todavía sin guardar':''} <button class="text-btn" data-action="back-editor" style="display:inline-flex;margin-left:15px">${icon('back')} Volver al panel</button></div>`:''}<main id="main" class="patient-shell patient-compact"><header class="patient-top">${brand()}<span class="status"><span class="dot"></span>Tu plan de ejercicios</span></header><section class="patient-welcome"><div><span class="eyebrow">BIENVENIDO</span><h1>${esc(r.label||'Nombre y apellido')}</h1><p>Esta va a ser la rutina que tenés que hacer en tu casa.</p></div><img src="assets/movement-hero.webp" alt="Hombre y mujer haciendo ejercicio" class="welcome-art"><div class="patient-summary"><span>${r.items.length} ejercicios</span><span>${grouped.length} bloques</span><span>Actualizado ${date(r.updated_at||new Date())}</span></div></section>${r.note?`<div class="notice patient-general-note" style="white-space:pre-wrap">${esc(r.note)}</div>`:''}${demo?'<div class="demo-banner patient-demo">Vista de prueba. Estas indicaciones son ejemplos para revisar la página.</div>':''}<div class="routine-compact-toolbar"><p>Tocá un ejercicio para ver el video y sus indicaciones.</p><button class="text-btn" id="toggle-all-videos" type="button" aria-expanded="false">Mostrar todos los videos</button></div><nav class="chip-row" aria-label="Bloques de tu rutina">${grouped.map(b=>`<a class="chip" style="text-decoration:none" href="#block-${blocks.indexOf(b)}">${b}</a>`).join('')}</nav>${grouped.map(b=>`<section class="patient-block" id="block-${blocks.indexOf(b)}" aria-label="Ejercicios de ${esc(b)}"><h2><span class="patient-block-symbol">${blockSymbol(b)}</span><span>${b}<small>BLOQUE ${String(grouped.indexOf(b)+1).padStart(2,'0')}</small></span></h2><div class="compact-exercises">${r.items.filter(x=>x.exercise.block===b).map(x=>`<details class="patient-exercise-row" ${items.indexOf(x)===0?'open':''}><summary class="exercise-summary"><span class="compact-exercise-name"><span class="compact-exercise-number">${String(items.indexOf(x)+1).padStart(2,'0')}</span><span>${esc(x.exercise.name)}</span></span><span class="compact-dose"><small>Carga</small><strong>${esc(x.weight||'—')}</strong></span><span class="compact-dose"><small>Repeticiones</small><strong>${esc(x.reps||'—')}</strong></span><span class="compact-dose"><small>Series</small><strong>${esc(x.series||'—')}</strong></span><span class="compact-video-toggle"><span class="when-closed">Ver video</span><span class="when-open">Ocultar video</span>${icon('down')}</span></summary><div class="exercise-expanded"><div class="exercise-media" data-media-slot><template>${mediaHTML(x.exercise)}</template></div>${x.exercise.notes||x.notes||x.hold||x.rest||x.frequency?`<div class="exercise-expanded-notes">${doseExtras(x)}${x.exercise.notes?`<p class="table-instructions">${esc(x.exercise.notes)}</p>`:''}${x.notes?`<p class="table-personal-note">${esc(x.notes)}</p>`:''}</div>`:''}</div></details>`).join('')}</div></section>`).join('')}<footer class="patient-footer"><img src="logo.svg" alt="" width="37" height="37" style="margin-bottom:12px"><strong>Tomás Bossio</strong><p>Acompañar el movimiento.</p><p class="tiny" style="margin-top:15px">Este enlace muestra tu rutina vigente. Volvé a abrirlo para consultar los cambios.</p>${!isPreview?'<button class="text-btn" data-action="refresh-patient" style="margin:10px auto">Actualizar rutina</button>':''}</footer></main>`;bind();bindPatientAccordions()}

function bindPatientAccordions(root=document){const rows=[...root.querySelectorAll('details.patient-exercise-row')],toggle=root.querySelector('#toggle-all-videos');if(!rows.length)return;let expandingAll=false;const templates=new Map(rows.map(row=>[row,row.querySelector('template')?.innerHTML||'']));const mount=row=>{const slot=row.querySelector('[data-media-slot]');if(!slot||slot.dataset.loaded==='true')return;slot.innerHTML=templates.get(row);slot.dataset.loaded='true';bindVideos(slot)};const unload=row=>{const slot=row.querySelector('[data-media-slot]');if(!slot)return;stopMedia(slot);slot.innerHTML='';slot.dataset.loaded='false'};const update=()=>{if(!toggle)return;const allOpen=rows.every(row=>row.open);toggle.textContent=allOpen?'Cerrar todos los videos':'Mostrar todos los videos';toggle.setAttribute('aria-expanded',String(allOpen))};rows.forEach(row=>{row.addEventListener('toggle',()=>{if(row.open){if(!expandingAll)rows.forEach(other=>{if(other!==row&&other.open){other.open=false;unload(other)}});mount(row)}else{unload(row);if(expandingAll)expandingAll=false}update()});if(row.open)mount(row)});if(toggle)toggle.onclick=()=>{const openAll=!rows.every(row=>row.open);expandingAll=openAll;rows.forEach(row=>{row.open=openAll;openAll?mount(row):unload(row)});update()};update()}

async function loadPatient(){app.innerHTML='<main class="loading">Buscando tu rutina…</main>';try{if(!config.supabaseUrl)throw Error('Esta página todavía está en preparación. Tu profesional te enviará el enlace cuando esté habilitada.');const r=await api('/rest/v1/rpc/get_patient_routine',{method:'POST',body:JSON.stringify({p_token:patientToken})},false);if(!r)throw Error('La rutina no está disponible. Puede estar pausada o el enlace no ser correcto. Consultá con Tomás.');patientView(r)}catch(e){app.innerHTML=`<main class="auth-wrap"><div class="panel">${brand()}<h1 style="margin-top:25px">No pudimos abrir tu rutina.</h1><p class="muted">${esc(e.message)}</p>${btn('Volver a intentar','refresh-patient','secondary')}</div></main>`;bind()}}
function renderSettings(){shell(`<div class="page-heading"><div><p class="eyebrow" style="margin:0 0 9px">UN ESPACIO PROPIO</p><h1>Todo en su lugar.</h1><p>Tu biblioteca y tus rutinas, separadas de KINÉDATA.</p></div></div><div class="editor-layout"><section class="panel"><h2 style="margin-bottom:15px">${demo?'Conectar tu cuenta gratuita':'Tu cuenta está conectada'}</h2><p class="small muted">${demo?'La página ya está preparada para guardar rutinas en línea con Supabase. Para habilitar los enlaces reales hay que completar esta configuración inicial.':'Las rutinas se guardan en tu base de datos. Los pacientes acceden con su enlace y no necesitan registrarse.'}</p><div class="setup-steps"><div class="setup-step"><h3>Crear tu proyecto gratuito</h3><p>Creá una cuenta en <a href="https://supabase.com/dashboard" target="_blank" rel="noopener noreferrer">Supabase</a> y un proyecto con plan Free. No hace falta contratar un plan pago.</p></div><div class="setup-step"><h3>Preparar la base de datos y tu acceso</h3><p>El archivo de instalación crea las tablas y las reglas de acceso. El administrador se habilita con el correo que vos elijas; no hay registro público.</p><a class="text-btn" href="instalacion.sql" download>Descargar instalación SQL ${icon('download')}</a></div><div class="setup-step"><h3>Configurar la página una sola vez</h3><p>Hay que colocar la URL del proyecto y su clave pública en config.json. Nunca uses una clave secreta ni service_role. Te acompaño en este paso.</p></div><div class="setup-step"><h3>Publicar en tu alojamiento independiente</h3><p>Los archivos de la página se pueden alojar en GitHub Pages. Así el uso no depende de ChatGPT Plus. Esta versión de revisión todavía no es el alojamiento definitivo.</p></div></div><div class="notice warn" style="margin-top:20px">${demo?'Todavía no compartas esta prueba con pacientes. La conexión en línea y el alojamiento independiente están pendientes.':'El alojamiento y la base de datos tienen sus propios límites y condiciones de servicio.'}</div></section><aside><div class="panel"><h3>Copias de tus datos</h3><p class="small muted">Descargá tus ejercicios y rutinas como respaldo. Los videos propios quedan en el almacenamiento del proyecto; el respaldo incluye sus enlaces.</p><div class="action-stack" style="margin-top:18px">${btn('Descargar respaldo','export','secondary','download')}${btn('Administrar videos propios','manage-videos','secondary','video')}${demo?btn('Reiniciar prueba','reset-demo','ghost'):btn('Cerrar sesión','logout','ghost','logout')}</div></div><div class="panel" style="margin-top:20px"><h3>Videos propios</h3><p class="small muted">Se guardan una sola vez, hasta 50 MB por archivo. YouTube evita consumir ese espacio. Seleccionar un fragmento controla la reproducción, sin recortar físicamente el archivo.</p></div></aside></div>`)}
function renderLogin(){app.innerHTML=`<main id="main" class="auth-wrap">${brand()}<section class="panel"><span class="eyebrow muted">TU ESPACIO PROFESIONAL</span><h1 style="margin-top:15px">Qué bueno verte.</h1><p class="muted">Ingresá para administrar tus ejercicios y rutinas.</p><form id="login-form"><div id="login-error" class="error-text" role="alert"></div><label class="field">Correo electrónico<input name="email" type="email" autocomplete="username" required></label><label class="field">Contraseña<input name="password" type="password" autocomplete="current-password" required></label><button class="btn" type="submit">Ingresar ${icon('arrow')}</button></form></section><p class="tiny muted" style="text-align:center;margin-top:20px">Tomás Bossio · Plan de rutina</p></main>`;$('#login-form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{const values=Object.fromEntries(new FormData(e.target));const r=await fetch(config.supabaseUrl+'/auth/v1/token?grant_type=password',{method:'POST',headers:{apikey:config.publishableKey,'Content-Type':'application/json'},body:JSON.stringify(values)});if(!r.ok)throw Error('No pudimos ingresar. Revisá tu correo y contraseña.');session=await r.json();sessionStorage.setItem('plan-session',JSON.stringify(session));const allowed=await api('/rest/v1/rpc/is_plan_admin',{method:'POST',body:'{}'});if(!allowed){session=null;sessionStorage.removeItem('plan-session');throw Error('Esta cuenta no tiene permiso para administrar los planes.')}await loadData();renderLibrary()}catch(err){$('#login-error').textContent=err.message;b.disabled=false}}}
function renderIntro(){startDemo()}
function startDemo(){demo=true;try{const saved=JSON.parse(localStorage.getItem('plan-rutina-demo-v1'));data=saved?.exercises&&saved?.routines?saved:demoSeed()}catch{data=demoSeed()}renderLibrary()}
async function navigate(id){if(dirty&&current==='editor'&&id!=='editor'){if(!await confirmDialog('¿Salir sin guardar?','Los cambios de esta rutina todavía no se guardaron.'))return;dirty=false}stopMedia(document);current=id;if(id==='library')renderLibrary();else if(id==='routines')renderRoutines();else renderSettings();window.scrollTo(0,0)}
function exportData(){const blob=new Blob([JSON.stringify({format:'plan-de-rutina-v1',exportedAt:new Date().toISOString(),...data},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='plan-de-rutina-respaldo-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function bind(root=document){root.querySelectorAll('[data-action]').forEach(el=>el.onclick=async ev=>{ev.preventDefault();const a=el.dataset.action,id=el.dataset.id;try{if(a==='brand'){if(patientToken||preview)window.scrollTo(0,0);else await navigate('library')}if(a==='nav')await navigate(id);if(a==='filter-block'){const y=window.scrollY;block=id;renderLibrary();window.scrollTo(0,y)}if(a==='new-exercise')exerciseForm();if(a==='edit-exercise')exerciseForm(id);if(a==='delete-exercise')await deleteExercise(id);if(a==='watch')watch(id);if(a==='close')closeModal();if(a==='start-demo')startDemo();if(a==='intro-settings'){startDemo();current='settings';renderSettings()}if(a==='new-routine'){newRoutine();window.scrollTo(0,0)}if(a==='edit-routine')editPlan(data.routines.find(r=>r.id===id));if(a==='assign'){modal('Agregar a una rutina',`<p class="small muted" style="margin-bottom:18px">Elegí un plan existente o creá uno nuevo.</p><div class="action-stack">${data.routines.map(r=>`<button class="btn secondary" data-add-plan="${esc(r.id)}">${esc(r.label)}</button>`).join('')}<button class="btn" id="assign-new">${icon('plus')}Crear una rutina</button></div>`);$('#assign-new').onclick=()=>{closeModal();newRoutine(id)};$$('[data-add-plan]').forEach(b=>b.onclick=()=>{const r=data.routines.find(x=>x.id===b.dataset.addPlan);draft=structuredClone(r);if(!draft.items.some(x=>x.exercise.id===id))draft.items.push(newPlanItem(getExercise(id)));dirty=true;current='editor';closeModal();renderEditor()})}if(a==='choose-exercises')chooseExercises();if(a==='remove-item'&&await confirmDialog('¿Quitar este ejercicio?','Se quitará de esta rutina cuando guardes los cambios. La biblioteca no se modifica.')){draft.items.splice(+id,1);markDirty();renderEditor()}if(a==='move-up'||a==='move-down'){const i=+id,b=draft.items[i].exercise.block;let j=i+(a==='move-up'?-1:1);while(j>=0&&j<draft.items.length&&draft.items[j].exercise.block!==b)j+=a==='move-up'?-1:1;if(j>=0&&j<draft.items.length){[draft.items[i],draft.items[j]]=[draft.items[j],draft.items[i]];markDirty();renderEditor()}}if(a==='block-up'||a==='block-down'){const bs=planBlocks(draft),i=bs.indexOf(id),j=i+(a==='block-up'?-1:1);if(j>=0&&j<bs.length){[bs[i],bs[j]]=[bs[j],bs[i]];draft.blockOrder=bs;markDirty();renderEditor()}}if(a==='refresh-item'&&await confirmDialog('¿Actualizar desde la biblioteca?','Se reemplazan el video y las indicaciones generales de este ejercicio. Tus series, repeticiones y carga se conservan.')){const e=getExercise(draft.items[+id].exercise.id);if(e){draft.items[+id].exercise=exerciseSnap(e);markDirty();renderEditor()}}if(a==='duplicate-routine')await duplicateRoutine(data.routines.find(r=>r.id===id));if(a==='duplicate-draft')await duplicateRoutine(draft);if(a==='delete-routine')await deleteRoutine(data.routines.find(r=>r.id===id));if(a==='delete-draft')await deleteRoutine(draft);if(a==='clear-history')await deleteHistory(null);if(a==='delete-history-version')await deleteHistory(+id);if(a==='whatsapp-draft')whatsapp(draft);if(a==='manage-videos')await manageVideos();if(a==='save-routine')await saveRoutine();if(a==='preview-draft'){if(!draft.items.length){toast('Primero seleccioná algún ejercicio.');return}patientView(draft,true);window.scrollTo(0,0)}if(a==='preview-routine'){draft=structuredClone(data.routines.find(r=>r.id===id));dirty=false;patientView(draft,true);window.scrollTo(0,0)}if(a==='back-editor'){preview=false;current='editor';renderEditor()}if(a==='share-routine')share(data.routines.find(r=>r.id===id));if(a==='share-draft')share(draft);if(a==='history')await showHistory();if(a==='refresh-patient')await loadPatient();if(a==='export')exportData();if(a==='reset-demo'&&await confirmDialog('¿Reiniciar la prueba?','Esto borra únicamente los datos de ejemplo guardados en este navegador.')){data=demoSeed();storeDemo();current='library';renderLibrary()}if(a==='logout'){try{await api('/auth/v1/logout',{method:'POST'})}finally{session=null;sessionStorage.removeItem('plan-session');renderLogin()}}}catch(e){toast(e.message)}})}

async function duplicateRoutine(r){if(dirty&&draft?.id===r.id){toast('Guardá los cambios antes de duplicar la rutina.');return}modal('Duplicar rutina',`<p class="small muted">Se copian ejercicios e indicaciones a una rutina independiente, con un enlace nuevo.</p><form id="duplicate-form"><label class="field" style="margin-top:20px">Nombre y apellido del nuevo paciente<input name="label" required maxlength="80" placeholder="Nombre y apellido" autocomplete="off"></label><div class="dialog-footer"><button type="button" class="btn secondary" data-action="close">Cancelar</button><button type="submit" class="btn">Crear copia</button></div></form>`);$('#duplicate-form').onsubmit=ev=>{ev.preventDefault();const name=new FormData(ev.target).get('label').trim();if(data.routines.some(x=>normalizeName(x.label)===normalizeName(name))){toast('Ya existe una rutina para este nombre. Editá esa rutina.');return}draft={id:uid(),label:name,token:uid()+uid().replaceAll('-',''),items:structuredClone(r.items),blockOrder:planBlocks(r),note:r.note,active:true,revision:0};dirty=true;current='editor';closeModal();renderEditor();toast('Copia preparada. Revisala y guardá los cambios.')}}
async function deleteRoutine(r){if(!await confirmDialog('¿Eliminar la rutina de '+esc(r.label)+'?','Se eliminan la rutina y su historial. Su enlace dejará de funcionar. La biblioteca y sus videos se conservan. Esta acción no se puede deshacer.'))return;try{if(!demo)await api('/rest/v1/rpc/delete_plan_routine',{method:'POST',body:JSON.stringify({p_id:r.id,p_expected_revision:r.revision})});data.routines=data.routines.filter(x=>x.id!==r.id);if(demo)storeDemo();if(draft?.id===r.id){draft=null;dirty=false}current='routines';renderRoutines();toast('Rutina eliminada.')}catch(e){toast(e.message)}}
async function deleteHistory(revision){const id=draft.id;if(!await confirmDialog(revision===null?'¿Borrar todas las versiones anteriores?':'¿Eliminar la versión '+revision+'?', 'La rutina vigente y su enlace se conservan. El historial eliminado no se puede recuperar.'))return;try{if(demo){const r=data.routines.find(r=>r.id===id);r.history=revision===null?[]:(r.history||[]).filter(h=>h.revision!==revision);if(draft.id===id)draft.history=structuredClone(r.history);storeDemo()}else await api('/rest/v1/rpc/delete_plan_history',{method:'POST',body:JSON.stringify({p_id:id,p_revision:revision})});await showHistory();toast('Historial actualizado. La rutina vigente se conservó.')}catch(e){toast(e.message)}}
function whatsapp(r){if(demo){toast('WhatsApp se habilita al conectar tu cuenta y publicar los enlaces reales.');return}if(dirty&&draft?.id===r.id){toast('Guardá los cambios antes de preparar el mensaje.');return}if(!r.active){toast('Activá y guardá la rutina antes de compartirla.');return}const url=routineURL(r),first=`Hola, ${r.label}. Te comparto tu rutina de ejercicios para hacer en casa:\n${url}\nUsá este mismo enlace para consultar las próximas actualizaciones.`,update=`Hola, ${r.label}. Hice modificaciones en tu rutina de ejercicios. Podés verlas abriendo el mismo enlace:\n${url}`;modal('Compartir por WhatsApp',`<p class="small muted">Se abre WhatsApp con el mensaje preparado. Vos elegís el destinatario, revisás y enviás.</p><h3 class="defaults-title">Primera entrega</h3><p class="message-preview">${esc(first)}</p><a class="btn" href="https://wa.me/?text=${encodeURIComponent(first)}" target="_blank" rel="noopener noreferrer">Abrir WhatsApp</a><h3 class="defaults-title">Avisar una actualización</h3><p class="message-preview">${esc(update)}</p><a class="btn secondary" href="https://wa.me/?text=${encodeURIComponent(update)}" target="_blank" rel="noopener noreferrer">Avisar cambios por WhatsApp</a>`)}
async function manageVideos(){if(demo){modal('Videos propios',`<p class="small muted">Esta función se habilita al conectar tu cuenta. Vas a poder ver el espacio ocupado y eliminar videos que ya no estén en la biblioteca, las rutinas o su historial.</p><div class="notice" style="margin-top:18px">Los enlaces de YouTube no ocupan espacio de archivos en tu cuenta.</div>`);return}try{let files=[],offset=0,page=[];do{page=await api('/storage/v1/object/list/exercise-videos',{method:'POST',body:JSON.stringify({prefix:'',limit:100,offset,sortBy:{column:'name',order:'asc'}})});files.push(...page.filter(f=>f.id));offset+=100}while(page.length===100);const refs=new Set(await api('/rest/v1/rpc/get_plan_video_references',{method:'POST',body:'{}'}));const used=f=>[...refs].some(u=>u.endsWith('/exercise-videos/'+f.name)),size=files.reduce((sum,f)=>sum+Number(f.metadata?.size||0),0);modal('Administrar videos propios',`<p class="small muted">${files.length} archivos · ${(size/1048576).toFixed(1)} MB. Se pueden eliminar los archivos sin referencias. Para liberar uno en uso, quitá sus ejercicios y las versiones anteriores que lo conservan.</p><div class="video-file-list">${files.map(f=>`<div class="video-file-row"><div><strong>${esc(f.name)}</strong><small>${(Number(f.metadata?.size||0)/1048576).toFixed(1)} MB · ${used(f)?'En uso':'Sin uso'}</small></div><button class="icon-btn" data-remove-file="${esc(f.name)}" aria-label="Eliminar video ${esc(f.name)}" ${used(f)?'disabled':''}>${icon('trash')}</button></div>`).join('')||'<div class="notice" style="margin-top:20px">Todavía no hay archivos propios guardados.</div>'}</div>`);$$('[data-remove-file]').forEach(b=>b.onclick=async()=>{const name=b.dataset.removeFile;if(!await confirmDialog('¿Eliminar este archivo de video?','Se borra del almacenamiento de forma definitiva. Esta acción no se puede deshacer.'))return;try{const fresh=await api('/rest/v1/rpc/get_plan_video_references',{method:'POST',body:'{}'});if(fresh.some(u=>u.endsWith('/exercise-videos/'+name)))throw Error('El video está en uso. Quitá primero sus referencias.');await api('/storage/v1/object/exercise-videos',{method:'DELETE',body:JSON.stringify({prefixes:[name]})});await manageVideos();toast('Archivo eliminado del almacenamiento.')}catch(e){toast(e.message)}})}catch(e){toast(e.message)}}

window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue=''}});
dialog.addEventListener('close',()=>{stopMedia(dialog);if(pendingURL){URL.revokeObjectURL(pendingURL);pendingURL=null}pendingFile=null});
window.addEventListener('online',()=>{if(patientToken)loadPatient()});
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&patientToken)loadPatient()});
async function init(){try{const r=await fetch('config.json',{cache:'no-store'});if(!r.ok)throw Error('No se pudo leer la configuración.');config=await r.json();if(config.supabaseUrl)config.supabaseUrl=config.supabaseUrl.replace(/\/$/,'');if(patientToken){await loadPatient();return}if(!config.supabaseUrl||!config.publishableKey){renderIntro();return}try{session=JSON.parse(sessionStorage.getItem('plan-session'))}catch{}if(session){try{await loadData();renderLibrary()}catch{session=null;renderLogin()}}else renderLogin()}catch(e){app.innerHTML=`<main class="auth-wrap"><div class="panel"><h1>No pudimos iniciar.</h1><p>${esc(e.message)}</p><button class="btn" onclick="location.reload()">Volver a intentar</button></div></main>`}}
init();
